                        ing_prot_var_spec_data = document['INGRESSPROTOCOLVARIANTSPECIFICDATA'].split(",")

                        URI = ing_prot_var_spec_data[2]
                        document["SIPURIPAI"]=URI
                        if URI:
                            phone = URI.split(':')[1].split('@')[0]
                            # print document['INGRESSPROTOCOLVARIANTSPECIFICDATA']+"<-TELEPHONE->"+phone
                            document["CALLERNUMBERSIPURIPAI"]=phone

                        callee_number_info = ing_prot_var_spec_data[8] if len(ing_prot_var_spec_data) >= 9 else None
                        if callee_number_info:  # != '' and is not None
                            match = self.callee_number_pattern.search(callee_number_info)
                            if match:
                                document['CALLEENUMBER'] = match.group(2)

                        # Remover coluna que ta no ficheiro e nao guardamos em BD pois colocamos o EventType
                        document.pop(line[0])

                        if document["INCOMINGCALLINGNUMBER"].startswith('351'):
                            document["INCOMINGCALLINGNUMBER"]='+'+document["INCOMINGCALLINGNUMBER"]

                        document["EVENTTYPE"]=line[0]
                        data_tmp=document["STARTTIMEDATE"]+' '+document["STARTTIMETIME"].split('.')[0]

                        data_time = datetime.strptime(data_tmp, "%m/%d/%Y %H:%M:%S")
                        data_time = datetime.strftime(data_time,"%Y-%m-%d %H:%M:%S")

                        data_disc=document["DISCONNECTTIMEDATE"]+' '+document["DISCONNECTTIMETIME"].split('.')[0]
                        data_disc = datetime.strptime(data_disc, "%m/%d/%Y %H:%M:%S")
                        data_disc = datetime.strftime(data_disc,"%Y-%m-%d %H:%M:%S")

                        document["STARTTIMEDATETIME"]=data_time

                        document["DISCONNECTTIMEDATETIME"]=data_disc

                        # Imprimir PKs
                        # print line[0]+'<->' + document["ACCOUNTINGID"]+'<->' + document["GATEWAYNAME"]+'<->' +document["STARTTIMEDATETIME"]

                        document["GRANULARITYPERIOD"]=15

