    def processEnrichFiles(self):
        endpoints = []
        # ordenar pelo mais recente
        for root, dirnames, filenames in sorted(os.walk('/opt/ptin/medrepo/synchronizedRepository/GENBAND/CFG/127.0.0.1'), reverse=True):
            for filename in sorted(fnmatch.filter(filenames, 'ENRICH*.csv'), reverse=True):
                filePath = os.path.join(root, filename)

                with open(filePath) as fp:
                    c = 1
                    for line in fp:
                        line = line.strip()
                        if line == 1:
                            tableName = line
                        elif line == 2:
                            dt = line
                        else:
                            if line not in endpoints:
                                endpoints.append(line)
                        c += 1

            # para so processar o ficheiro mais recente
            return endpoints
        # se nao encontrar ficheiros
        return None

    def enrichment(self, ingresstrunk, egresstrunk):
        callType=''

        if ingresstrunk in self.__endpoints and egresstrunk in self.__endpoints:
            callType="Incoming/Outgoing"

        elif ingresstrunk in self.__endpoints:
            callType= "Outgoing"

        elif egresstrunk in self.__endpoints:
            callType= "Incoming"

        return callType
